import{_ as n,C as t,o as s,c as r,ah as a,E as i}from"./chunks/framework.sPHStHqt.js";const m=JSON.parse('{"title":"The Tenant Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"tenants/tenant-workspace.md","filePath":"tenants/tenant-workspace.md","lastUpdated":1789630599000}'),l={name:"tenants/tenant-workspace.md"};function u(d,e,p,c,h,g){const o=t("ImagePopup");return s(),r("div",null,[e[0]||(e[0]=a('<h1 id="the-tenant-workspace" tabindex="-1">The Tenant Workspace <a class="header-anchor" href="#the-tenant-workspace" aria-label="Permalink to &quot;The Tenant Workspace&quot;">​</a></h1><p><em>This page is for a <strong>tenant</strong> — a business using the CRM it signed up for.</em></p><p>Once you&#39;ve registered, you have a complete Krayin CRM of your own. This page is a quick tour of what&#39;s inside and how it&#39;s yours alone.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where to sign in and what you&#39;ll see</li><li>What&#39;s in your workspace</li><li>How your data stays private to you</li></ul></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Your CRM lives at your own address — <code>yourusername.yourplatform.com</code> — and you sign in at <code>/admin/login</code> there with the email and password you registered with.</p>',6)),i(o,{src:"/images/tenant-workspace/tenant-dashboard.png",alt:"A tenant's CRM dashboard"}),e[1]||(e[1]=a('<p>The dashboard greets you with the numbers that matter — lead value, total leads, quotations, contacts and organizations, your open leads by stage, and revenue charts — all drawn from <em>your</em> data.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><p>Your workspace is a full CRM. From the sidebar you can reach:</p><ul><li><strong>Leads</strong> — your sales opportunities, moving through pipeline stages.</li><li><strong>Quotes</strong> — quotations you send to your contacts.</li><li><strong>Contacts</strong> and <strong>Organizations</strong> — the people and companies you work with.</li><li><strong>Mail</strong>, <strong>Activities</strong> and <strong>Products</strong> — the tools around your day-to-day selling.</li><li><strong>Settings</strong> — your own users, roles, pipelines and preferences.</li><li><strong>Subscription</strong> — your plan and invoices (see <a href="/tenants/billing-and-invoices">Billing &amp; Invoices</a>).</li></ul><p>It&#39;s an ordinary Krayin CRM — everything Krayin does, you have.</p><h2 id="it-s-entirely-yours" tabindex="-1">It&#39;s entirely yours <a class="header-anchor" href="#it-s-entirely-yours" aria-label="Permalink to &quot;It&#39;s entirely yours&quot;">​</a></h2><p>Everything in your workspace belongs to you and only you. You can&#39;t see another business&#39;s leads or contacts, and no other tenant can see yours — the platform keeps every tenant&#39;s data completely separate. You manage your own team, your own pipelines and your own settings, independently of everyone else on the platform.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your subscription decides your limits — how many team members, leads or contacts you can create. When you approach a limit, you&#39;ll be prompted to upgrade. See <a href="/tenants/choosing-a-plan">Choosing a Plan</a>.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Manage your plan and download invoices → <a href="/tenants/billing-and-invoices">Billing &amp; Invoices</a></li><li>Move to a bigger plan when you outgrow yours → <a href="/tenants/choosing-a-plan">Choosing a Plan</a></li><li>Put your CRM on your own domain → <a href="/tenants/custom-domains">Custom Domains</a></li></ul>',10))])}const w=n(l,[["render",u]]);export{m as __pageData,w as default};
